using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using MaintenancePRO.Api.Models; using Microsoft.AspNetCore.Identity; using Microsoft.IdentityModel.Tokens;
namespace MaintenancePRO.Api.Security;
public sealed class TokenService(IConfiguration c,UserManager<ApplicationUser> users){public async Task<string> CreateAsync(ApplicationUser u){var claims=new List<Claim>{new(JwtRegisteredClaimNames.Sub,u.Id),new(JwtRegisteredClaimNames.Email,u.Email??""),new(ClaimTypes.NameIdentifier,u.Id),new(ClaimTypes.Name,u.UserName??u.Email??"")}; foreach(var role in await users.GetRolesAsync(u))claims.Add(new Claim(ClaimTypes.Role,role)); var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(c["Jwt:Key"]!)); var token=new JwtSecurityToken(c["Jwt:Issuer"],c["Jwt:Audience"],claims,DateTime.UtcNow,DateTime.UtcNow.AddMinutes(15),new SigningCredentials(key,SecurityAlgorithms.HmacSha256));return new JwtSecurityTokenHandler().WriteToken(token);}}
